#include <algorithm>
#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> q;
    unordered_map<string, int> idOf;
    vector<string> names;
    vector<char> exists, active;
    vector<long long> cnt;
    vector<int> stamp;
    auto id = [&](const string &s) {
        auto it = idOf.find(s);
        if (it != idOf.end()) return it->second;
        int x = names.size();
        idOf.emplace(s, x);
        names.push_back(s);
        exists.push_back(0);
        active.push_back(0);
        cnt.push_back(0);
        stamp.push_back(-1);
        return x;
    };
    vector<int> users;  // ids in the order they first sent a message
    for (int e = 0; e < q; e++) {
        string type, user;
        cin >> type >> user;
        if (type == "OFFLINE") {
            active[id(user)] = 0;
            continue;
        }
        int sender = id(user);
        if (!exists[sender]) {
            exists[sender] = 1;
            users.push_back(sender);
        }
        active[sender] = 1;
        long long ts;
        int m;
        cin >> ts >> m;
        vector<int> mentioned;
        auto mention = [&](int u) {
            if (stamp[u] != e) {  // count each user at most once per message
                stamp[u] = e;
                mentioned.push_back(u);
            }
        };
        for (int i = 0; i < m; i++) {
            string tok;
            cin >> tok;
            if (tok == "ALL") {
                for (int u : users) mention(u);
            } else if (tok == "HERE") {
                for (int u : users)
                    if (active[u]) mention(u);
            } else {
                mention(id(tok));
            }
        }
        for (int u : mentioned) cnt[u]++;
    }
    vector<int> order;
    for (size_t u = 0; u < names.size(); u++)
        if (cnt[u] > 0) order.push_back(u);
    sort(order.begin(), order.end(), [&](int a, int b) { return names[a] < names[b]; });
    string out;
    for (size_t i = 0; i < order.size(); i++) {
        if (i) out += ' ';
        out += names[order[i]] + '=' + to_string(cnt[order[i]]);
    }
    out += '\n';
    cout << out;
}

import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int q = (int) nextLong();
        LinkedHashSet<String> users = new LinkedHashSet<>();
        HashSet<String> active = new HashSet<>();
        TreeMap<String, Integer> cnt = new TreeMap<>();
        for (int e = 0; e < q; e++) {
            String type = next(), user = next();
            if (type.equals("OFFLINE")) {
                active.remove(user);
                continue;
            }
            users.add(user);
            active.add(user);
            nextLong();  // timestamp: events are already in order
            int m = (int) nextLong();
            HashSet<String> mentioned = new HashSet<>();  // each user counts once per message
            for (int i = 0; i < m; i++) {
                String tok = next();
                if (tok.equals("ALL")) mentioned.addAll(users);
                else if (tok.equals("HERE")) mentioned.addAll(active);
                else mentioned.add(tok);
            }
            for (String u : mentioned) cnt.merge(u, 1, Integer::sum);
        }
        StringBuilder out = new StringBuilder();
        for (Map.Entry<String, Integer> en : cnt.entrySet()) {
            if (out.length() > 0) out.append(' ');
            out.append(en.getKey()).append('=').append(en.getValue());
        }
        System.out.println(out);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	q := int(nextInt())
	var users []string // senders, in the order they first posted
	exists := map[string]bool{}
	active := map[string]bool{}
	cnt := map[string]int{}
	for e := 0; e < q; e++ {
		typ, user := nextToken(), nextToken()
		if typ == "OFFLINE" {
			delete(active, user)
			continue
		}
		if !exists[user] {
			exists[user] = true
			users = append(users, user)
		}
		active[user] = true
		nextInt() // timestamp: events are already in order
		m := int(nextInt())
		mentioned := map[string]bool{} // each user counts once per message
		for i := 0; i < m; i++ {
			switch tok := nextToken(); tok {
			case "ALL":
				for _, u := range users {
					mentioned[u] = true
				}
			case "HERE":
				for u := range active {
					mentioned[u] = true
				}
			default:
				mentioned[tok] = true
			}
		}
		for u := range mentioned {
			cnt[u]++
		}
	}
	names := make([]string, 0, len(cnt))
	for u := range cnt {
		names = append(names, u)
	}
	slices.Sort(names)
	out := []byte{}
	for i, u := range names {
		if i > 0 {
			out = append(out, ' ')
		}
		out = append(out, u...)
		out = append(out, '=')
		out = strconv.AppendInt(out, int64(cnt[u]), 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
